using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Xml.Linq;
namespace JingFamily {
 public static class LibraryTests {
  public static int Run(string dir){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Library test: "+label);count++;};Action<Action,string> reject=(a,label)=>{bool caught=false;try{a();}catch{caught=true;}check(caught,label);};string root=Path.Combine(dir,"multi-family");Directory.CreateDirectory(root);Library.Ready=false;Store.Root=root;Store.Data=Store.Sample();string original=Path.Combine(dir,"original-photo.png");using(var b=new Bitmap(40,40)){using(var g=Graphics.FromImage(b))g.Clear(Color.DarkGreen);b.Save(original);}string media=Store.AddMedia(original);Store.Data.People[0].Portrait=media;Store.Data.Documents.Add(new Document{Title="家族照片",PersonId=Store.Data.People[0].Id,File=media});Store.Data.Tasks.Add(new ResearchTask{Title="查旧档案",PersonId=Store.Data.People[0].Id});Store.Save();byte[] oldBytes=File.ReadAllBytes(Store.FilePath);Library.Initialize(root);check(Library.Index.Families.Count==1&&Library.Index.ActiveId=="legacy","legacy catalog migration");check(File.ReadAllBytes(Path.Combine(root,"family.xml")).SequenceEqual(oldBytes),"legacy data untouched");check(Store.Data.People.Count==7&&File.Exists(Path.Combine(Store.Root,media)),"legacy media available");
   var second=Library.Create("王氏家谱");check(Library.Index.ActiveId=="legacy","create does not silently switch");Library.Open(second.Id);check(Store.Data.People.Count==0,"new family blank");Store.Data.People.Add(new Person{Name="王某"});Store.Data.Tasks.Add(new ResearchTask{Title="王家待办"});Store.Save();string secondRoot=Store.Root;Library.Open("legacy");check(Store.Data.People.Count==7&&Store.Data.Tasks[0].Title=="查旧档案","switch restores independent people tasks");check(Store.Root!=secondRoot,"separate directories");
   var copy=Library.Copy("legacy","景家副本");check(Library.ReadFamily(copy.Id).People.Count==7&&Library.ReadFamily(copy.Id).Documents.Count==1,"copy people and documents");check(File.ReadAllBytes(Path.Combine(Library.RootFor(copy.Id),media)).SequenceEqual(File.ReadAllBytes(Path.Combine(root,media))),"copy attachments");Library.Open(copy.Id);Store.Data.People[0].Name="副本修改";Store.Save();check(Library.ReadFamily("legacy").People[0].Name=="景明远","copy edits isolated");Library.Rename(second.Id,"王氏家谱 · 修订");check(Library.ReadFamily(second.Id).Title=="王氏家谱 · 修订"&&Store.Data.Title=="景家副本","inactive rename isolated");Library.Rename(copy.Id,"景家副本 · 新名");check(Store.Data.Title=="景家副本 · 新名","active rename refreshes data");
   string backup=Path.Combine(dir,"one-family.zip");string activeRoot=Store.Root;Library.Export("legacy",backup);System.Collections.Generic.Dictionary<string,byte[]> files;var backed=Store.ReadBackup(backup,out files);check(backed.People[0].Name=="景明远"&&files.Count==1,"selected family backup");check(Store.Root==activeRoot&&Store.Data.Title=="景家副本 · 新名","backup does not switch context");var imported=Library.ImportBackup(backup,"从备份新增");check(Library.ReadFamily(imported.Id).Tasks.Count==1&&File.Exists(Path.Combine(Library.RootFor(imported.Id),media)),"import backup into independent family");check(Library.Index.ActiveId==copy.Id,"import does not alter active");
   Library.Remove(second.Id);check(!Directory.Exists(secondRoot)&&Library.Index.Trash.Count==1,"delete moves folder to trash");string trashId=Library.Index.Trash[0].TrashId;var recovered=Library.Restore(trashId);check(recovered.Id==second.Id&&Library.ReadFamily(recovered.Id).People.Single().Name=="王某","restore managed family");Library.Open(imported.Id);Library.Remove(imported.Id);check(Library.Index.ActiveId!=imported.Id&&Store.Root!=Library.RootFor(imported.Id),"delete active switches safely");var removed=Library.Index.Trash.Single(x=>x.Entry.Id==imported.Id);Library.Restore(removed.TrashId);check(Library.ReadFamily(imported.Id).People.Count==7,"restore active deleted data");
   Library.Open("legacy");Library.Remove("legacy");check(File.Exists(Library.IndexPath)&&Directory.Exists(Path.Combine(root,"families")),"legacy delete preserves catalog and other families");check(!File.Exists(Path.Combine(root,"family.xml")),"legacy archived");var legacyTrash=Library.Index.Trash.Single(x=>x.Entry.Id=="legacy");var restoredLegacy=Library.Restore(legacyTrash.TrashId);check(restoredLegacy.Id!="legacy"&&Library.ReadFamily(restoredLegacy.Id).People.Count==7,"legacy restored into managed directory");check(File.Exists(Path.Combine(Library.RootFor(restoredLegacy.Id),media)),"legacy attachment restore");Library.Open(restoredLegacy.Id);string remembered=Library.Index.ActiveId;Library.Initialize(root);check(Library.Index.ActiveId==remembered&&Store.Data.People.Count==7,"relaunch remembers current family");
   string file=Path.Combine(Library.RootFor(second.Id),"family.xml");File.Move(file,file+".test-moved");string oldActive=Library.Index.ActiveId;reject(()=>Library.Open(second.Id),"missing file switch rejected");check(Library.Index.ActiveId==oldActive&&Store.Data.People.Count==7,"failed switch preserves current");File.Move(file+".test-moved",file);reject(()=>Library.Child("families","../outside"),"directory traversal rejected");reject(()=>Library.Rename(second.Id,""),"empty name rejected");
   string single=Path.Combine(dir,"single-library");Library.Initialize(single);check(Library.Index.Families.Count==1&&File.Exists(Store.FilePath),"fresh library initial family");reject(()=>Library.Remove(Library.Index.ActiveId),"last family protected");Library.Initialize(root);check(Library.Summaries().Count==4,"list all separate families");
   using(var panel=new LibraryPanel(()=>{})){panel.Size=new Size(1140,690);panel.CreateControl();panel.PerformLayout();using(var b=new Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(dir,"家谱管理预览.png"));}count++;}using(var win=new MainWindow()){typeof(MainWindow).GetMethod("Navigate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(win,new object[]{"家谱管理"});count++;}
   using(var editor=new PersonEditor(Store.Data.People[0]))check(editor.Icon!=null,"editor branded icon");using(var preview=new ImportPreview(Templates.ReadRows(Templates.ParseCsv("编号,姓名\r\n1,甲"),"test")))check(preview.Icon!=null&&preview.Text.Contains(Store.Data.Title),"import branded and target named");using(var dialog=new BrandMessage("提示","测试",false))check(dialog.Icon!=null,"branded message dialog");using(var name=new NameEditor("名称","家谱"))check(name.Icon!=null,"family name dialog brand");using(var logo=Ui.Logo())using(var generated=BrandMark.Render(256))check(logo.GetPixel(128,58).ToArgb()==generated.GetPixel(128,58).ToArgb(),"shared logo master");
   using(var tree=new FamilyTree()){tree.Relayout();string svg=Path.Combine(dir,"统一Logo图谱.svg");tree.ExportSvg(svg);XNamespace ns="http://www.w3.org/2000/svg";var xml=XDocument.Load(svg);check(xml.Descendants(ns+"g").Any(x=>(string)x.Attribute("aria-label")=="景·谱 Logo"),"diagram uses shared vector logo");check(!xml.Descendants(ns+"text").Any(x=>x.Value=="谱"),"seal removed");}string html=Path.Combine(dir,"branded-book.html");Reports.ExportHtml(html);check(File.ReadAllText(html).Contains(BrandMark.HtmlImage(56)),"HTML book uses shared logo");return count;
  }
 }
}
